select case when s.rating >= 3.7 then 'high' when s.rating >= 2.4 then 'mid' else 'low' end as rating_bucket, case when s.country in ('JP', 'TH') then 'tier_1' else 'other' end as country_group, min(p.launch_date) as min_launch_date, count(case when p.category = 'Sports' then 1 end) as sports_count from products p join suppliers s on p.supplier_id = s.id group by case when s.rating >= 3.7 then 'high' when s.rating >= 2.4 then 'mid' else 'low' end, case when s.country in ('JP', 'TH') then 'tier_1' else 'other' end order by rating_bucket desc
